export interface AppConfig {
  port: number;
  host: string;
  debug?: boolean;
}

export function validateConfig(raw: unknown): AppConfig {
  if (typeof raw !== 'object' || raw === null) throw new Error('Invalid config object');
  const obj = raw as Record<string, unknown>;
  if (typeof obj.port !== 'number' || typeof obj.host !== 'string') throw new Error('Field mismatch');
  return { port: obj.port, host: obj.host, debug: Boolean(obj.debug) };
}
